<?php require 'includes/functions.php';$u=require_user();$pageTitle='Checkout';$errors=[];$items=cart_items();if(!$items){flash('Your bag is empty.');redirect('cart.php');}$_SESSION['checkout_token']??=bin2hex(random_bytes(32));if(post()){verify_csrf();$name=textval('customer_name');$phone=textval('phone');$address=textval('address');if(mb_strlen($name)<2||mb_strlen($name)>100)$errors[]='Enter your full name (2–100 characters).';if(!preg_match('/^[+0-9 ()-]{7,25}$/',$phone))$errors[]='Enter a valid phone number.';if(mb_strlen($address)<10||mb_strlen($address)>500)$errors[]='Enter a complete delivery address (10–500 characters).';if(!hash_equals($_SESSION['checkout_token'],textval('checkout_token')))$errors[]='Checkout expired. Reload this page.';if(!$errors){$pdo=db();try{$pdo->beginTransaction();$locked=[];$cart=$_SESSION['cart'];ksort($cart);foreach($cart as $id=>$qty){$p=query('SELECT * FROM products WHERE id=? FOR UPDATE',[$id])->fetch();if(!$p||!available($p)||$qty>$p['stock'])throw new RuntimeException('A fragrance is unavailable or its stock has changed. Please update your bag.');$p['quantity']=$qty;$locked[]=$p;}$total=totals($locked);query('INSERT INTO orders(user_id,customer_name,email,phone,address,subtotal,shipping,total,checkout_token) VALUES (?,?,?,?,?,?,?,?,?)',[$u['id'],$name,$u['email'],$phone,$address,$total['subtotal'],$total['shipping'],$total['total'],$_SESSION['checkout_token']]);$order=(int)$pdo->lastInsertId();foreach($locked as $p){query('INSERT INTO order_items(order_id,product_id,product_name,unit_price,quantity) VALUES (?,?,?,?,?)',[$order,$p['id'],$p['name'],$p['price'],$p['quantity']]);query('UPDATE products SET stock=stock-? WHERE id=?',[$p['quantity'],$p['id']]);}$pdo->commit();unset($_SESSION['cart'],$_SESSION['checkout_token']);flash('Order #'.$order.' placed. Payment is due on delivery.');redirect('dashboard.php');}catch(RuntimeException $e){if($pdo->inTransaction())$pdo->rollBack();if($e instanceof PDOException){error_log((string)$e);$errors[]='Unable to place the order. Check your order history before retrying.';}else $errors[]=$e->getMessage();}}}$total=totals($items);require 'includes/header.php';?><section class="container section"><span class="eyebrow">ONE STEP CLOSER</span><h1>Checkout</h1><?php errors($errors);?><div class="checkout-grid"><form method="post" class="panel" data-validate><?php csrf();?><input type="hidden" name="checkout_token" value="<?=e($_SESSION['checkout_token'])?>"><h2>Delivery details</h2><label>Full name<input name="customer_name" minlength="2" maxlength="100" autocomplete="name" required value="<?=e(textval('customer_name'))?>"></label><label>Phone<input name="phone" type="tel" minlength="7" maxlength="25" autocomplete="tel" required value="<?=e(textval('phone'))?>"></label><label>Delivery address<textarea name="address" minlength="10" maxlength="500" rows="4" autocomplete="street-address" required><?=e(textval('address'))?></textarea></label><p>Payment method: <strong>Cash on delivery</strong></p><button>Place order · <?=money($total['total'])?></button></form><aside class="panel summary"><h2>Order summary</h2><?php foreach($items as $p):?><div><span><?=e($p['name'])?> × <?=$p['quantity']?></span><b><?=money($p['price']*$p['quantity'])?></b></div><?php endforeach;?><div>Delivery <b><?=money($total['shipping'])?></b></div><div class="total">Total <b><?=money($total['total'])?></b></div><p class="muted small">Final stock and prices are checked when you place your order.</p><a href="<?=e(url('cart.php'))?>">Edit shopping bag</a></aside></div></section><?php require 'includes/footer.php';?>
